package run.ikaros.password; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class PasswordDeviceService{private final PasswordDeviceRepository devices;public PasswordDeviceService(PasswordDeviceRepository d){devices=d;}public Mono<PasswordDeviceView> register(UUID a,RegisterDeviceRequest q){Instant n=Instant.now();return devices.save(new PasswordDeviceEntity(null,a,q.name().trim(),q.deviceType(),DeviceTrustState.TRUSTED,null,null,n,n,null)).map(this::view);}public Flux<PasswordDeviceView> list(UUID a){return devices.findAllByOwnerIdOrderByCreatedAtDesc(a).take(100).map(this::view);}public Mono<PasswordDeviceView> revoke(UUID a,UUID id){return own(a,id).flatMap(d->devices.save(new PasswordDeviceEntity(d.id(),d.ownerId(),d.name(),d.deviceType(),DeviceTrustState.REVOKED,d.lastSyncAt(),d.lastUnlockAt(),d.createdAt(),Instant.now(),d.version()))).map(this::view);}public Mono<PasswordDeviceView> touchSync(UUID a,UUID id){return own(a,id).filter(d->d.trustState()==DeviceTrustState.TRUSTED).switchIfEmpty(Mono.error(new NotFoundException("设备不存在、已撤销或无权访问"))).flatMap(d->devices.save(new PasswordDeviceEntity(d.id(),d.ownerId(),d.name(),d.deviceType(),d.trustState(),Instant.now(),d.lastUnlockAt(),d.createdAt(),Instant.now(),d.version()))).map(this::view);}private Mono<PasswordDeviceEntity> own(UUID a,UUID id){return devices.findById(id).filter(d->d.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("设备不存在或无权访问")));}private PasswordDeviceView view(PasswordDeviceEntity d){return new PasswordDeviceView(d.id(),d.name(),d.deviceType(),d.trustState(),d.lastSyncAt(),d.lastUnlockAt(),d.createdAt());}}
